export const getVerifyPaymentUrl = () => {




  return `/api/payments/verify`
}

/**
 * Called by the browser immediately after Razorpay's checkout handler fires. The server verifies the HMAC signature over `order_id|payment_id` using RAZORPAY_KEY_SECRET and, if valid, activates the payment (invoice, subscription, account access, commission).
This is the same activation the webhook performs and the two are idempotent, so whichever arrives first wins. It exists because the webhook is an inbound call from Razorpay and can never reach a server running on localhost — without it, sandbox/local payments would stay pending forever.

 * @summary Verify a completed Razorpay checkout and activate the subscription
 */
